using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using LWS.TruckSports.Editor;
namespace LWS.TruckBowling.Editor {
public static class BowlingReboundAuthoring {
 public static void Upgrade(){EditorSceneManager.OpenScene(BowlingAuthoring.Scene);Install(UnityEngine.Object.FindAnyObjectByType<BowlingMatch>());EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());AssetDatabase.SaveAssets();Validate();}
 public static void Install(BowlingMatch m){var teal=SportsEventAuthoring.Mat("TruckBowling","Spring-back woven bed",new Color(.025f,.38f,.43f),.18f);var metal=SportsEventAuthoring.Mat("TruckBowling","Spring-back satin frame",new Color(.32f,.38f,.43f),.55f);metal.SetFloat("_Metallic",.7f);var edge=SportsEventAuthoring.Contact("TruckBowling","Pin containment contact",.12f,.12f);var coil=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/TruckBeerPong/Models/Seven-turn visible launch spring.asset");if(coil==null)throw new Exception("Existing modeled spring mesh required");foreach(var lane in m.lanes){var wall=lane.GetComponentsInChildren<Transform>(true).First(t=>t.name=="Pit bumper");wall.position=new Vector3(lane.center,.55f,lane.pinLine+7);wall.localScale=new Vector3(5.4f,1.8f,.3f);var response=wall.GetComponent<BowlingReboundWall>()??wall.gameObject.AddComponent<BowlingReboundWall>();lane.rebound=response;response.lane=lane;response.pinContainment=new Collider[2];var prior=wall.Find("Spring-back presentation");if(prior!=null)UnityEngine.Object.DestroyImmediate(prior.gameObject);var root=new GameObject("Spring-back presentation").transform;root.SetParent(wall,false);root.localScale=new Vector3(1/wall.localScale.x,1/wall.localScale.y,1/wall.localScale.z);var bed=SportsEventAuthoring.Box("Flexible woven trampoline return bed",new Vector3(0,0,-.16f),new Vector3(4.8f,1.5f,.12f),teal,null,root).transform;response.bed=bed;for(int side=-1;side<=1;side+=2){SportsEventAuthoring.Box("Trampoline frame upright",new Vector3(side*2.55f,0,-.15f),new Vector3(.16f,1.8f,.24f),metal,null,root);for(int i=0;i<4;i++){var spring=new GameObject("Visible tension spring "+side+" / "+i).transform;spring.SetParent(root,false);spring.localPosition=new Vector3(side*2.43f,-.6f+i*.4f,-.18f);spring.localRotation=Quaternion.Euler(0,0,90);spring.localScale=new Vector3(.12f,.3f,.12f);spring.gameObject.AddComponent<MeshFilter>().sharedMesh=coil;spring.gameObject.AddComponent<MeshRenderer>().sharedMaterial=metal;}}for(int side=-1;side<=1;side+=2){var name="Physical rear-deck pin containment "+side;var p=lane.transform.Find(name);if(p!=null)UnityEngine.Object.DestroyImmediate(p.gameObject);response.pinContainment[side<0?0:1]=SportsEventAuthoring.Box(name,new Vector3(lane.center+side*2.66f,.6f,lane.pinLine+3.2f),new Vector3(.15f,2,7.2f),metal,edge,lane.transform).GetComponent<Collider>();}foreach(var c in response.pinContainment)c.gameObject.layer=2;foreach(var wheel in lane.truck.wheels)wheel.layerMask&=~(1<<2);lane.settleLimit=12;EditorUtility.SetDirty(lane);}}
 public static void Validate(){var m=UnityEngine.Object.FindAnyObjectByType<BowlingMatch>();if(m==null)throw new Exception("Bowling match required");foreach(var lane in m.lanes)if(lane.rebound==null||lane.rebound.lane!=lane||lane.rebound.bed==null||lane.rebound.pinContainment==null||lane.rebound.pinContainment.Length!=2||lane.rebound.pinContainment.Any(c=>c==null)||Mathf.Abs(lane.rebound.transform.position.z-lane.pinLine-7)>.01f||lane.settleLimit<12)throw new Exception("Rebound scene references invalid");Debug.Log("BOWLING_REBOUND_NATIVE_VALIDATED");}
}
}
